package com.ozyman.holomemflicker

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/**
 * The overlay coach's engine (Puka.kt) against the Coach screen's own engine
 * (assets/puka-coach.html): 160 positions from random games, generated by running the page's
 * script in node (see the fixture). Same legal moves in the same order, same positions after
 * each move, same evaluation, and the same best move and score at a fixed depth.
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class PukaTest {
    private fun fixtures(): JSONArray =
        JSONArray(javaClass.classLoader!!.getResourceAsStream("puka-fixtures.json").bufferedReader().readText())

    private fun state(o: JSONObject): Puka.State {
        val b = o.getJSONArray("b")
        val h0 = o.getJSONArray("h0"); val h1 = o.getJSONArray("h1")
        val h = IntArray(10)
        for (t in 0..4) { h[t] = h0.getInt(t); h[5 + t] = h1.getInt(t) }
        return Puka.State(IntArray(12) { b.getInt(it) }, h, o.getInt("turn"))
    }

    @Test
    fun matchesThePageEngine() {
        val fx = fixtures()
        assertTrue(fx.length() >= 100)
        for (n in 0 until fx.length()) {
            val o = fx.getJSONObject(n)
            val s = state(o)
            assertEquals("eval #$n", o.getDouble("eval"), Puka.evaluate(s), 1e-9)
            val kids = o.getJSONArray("kids")
            val ms = Puka.moves(s)
            assertEquals("move count #$n", kids.length(), ms.size)
            for ((k, m) in ms.withIndex()) {
                val e = kids.getJSONArray(k)
                assertEquals("move #$n.$k", listOf(e.getInt(0), e.getInt(1), e.getInt(2)), listOf(m.from, m.to, m.drop))
                val c = Puka.apply(s, m)
                assertEquals("board #$n.$k", e.getString(3), c.b.joinToString(","))
                assertEquals("hands #$n.$k", e.getString(4) + "|" + e.getString(5), (0..4).joinToString("") { c.h[it].toString() } + "|" + (5..9).joinToString("") { c.h[it].toString() })
                assertEquals(e.getInt(6), c.turn)
                assertEquals("terminal #$n.$k", e.getInt(7), Puka.terminal(c))
                assertEquals("child eval #$n.$k", e.getDouble(8), Puka.evaluate(c), 1e-9)
            }
            val r = Puka.search(s, Long.MAX_VALUE / 4, maxDepth = 4)!!
            val best = o.getJSONArray("best")
            assertEquals("best move #$n", listOf(best.getInt(0), best.getInt(1), best.getInt(2)), listOf(r.move.from, r.move.to, r.move.drop))
            assertEquals("score #$n", o.getDouble("score"), r.score, 1e-9)
            assertEquals("depth #$n", o.getInt("depth"), r.depth)
        }
    }

    @Test
    fun findsTheWinningCapture() {
        // their Leader is one step from your Whale: take it
        val s = Puka.empty(0)
        s.b[Puka.index(0, 1)] = Puka.LEADER // your Leader, middle of your back column
        s.b[Puka.index(3, 1)] = Puka.LEADER or 8
        s.b[Puka.index(2, 0)] = Puka.WHALE // diagonal to their Leader
        val r = Puka.search(s, 2000)!!
        assertEquals(Puka.index(3, 1), r.move.to)
        assertTrue(r.score > Puka.MATE - 100)
    }

    @Test
    fun rankPutsTheBestReplyFirst() {
        val s = Puka.empty(1)
        s.b[Puka.index(0, 1)] = Puka.LEADER
        s.b[Puka.index(3, 1)] = Puka.LEADER or 8
        s.b[Puka.index(1, 0)] = Puka.DOLPHIN or 8 // their Dolphin can take your Leader? no: next to it diagonally
        s.b[Puka.index(1, 1)] = Puka.DOLPHIN or 8 // straight in front of your Leader: takes it
        val r = Puka.rank(s, 2000)
        assertEquals(Puka.index(0, 1), r.first().first.to)
        assertEquals(Puka.moves(s).size, r.size)
    }

    @Test
    fun screenMappingRoundTrips() {
        for (i in 0 until 12) assertEquals(i, Puka.index(Puka.screenX(i), Puka.screenY(i)))
        // your Leader starts in the middle of the left column
        assertEquals(Puka.LEADER, Puka.start().b[Puka.index(0, 1)])
        assertEquals(Puka.LEADER or 8, Puka.start().b[Puka.index(3, 1)])
    }
}
